using System.Reflection;
using System.Text;

var options = Arguments.Parse(args);
var model = Assembly.LoadFrom(options.Model);
ValidateContract(model);
var generated = Render(model.GetName().Version?.ToString() ?? "unknown");

if (options.Check)
{
    if (!File.Exists(options.Output) || File.ReadAllText(options.Output) != generated)
        throw new InvalidOperationException("Generated protocol DTOs differ. Run the generator without --check and commit the result.");
    return;
}

Directory.CreateDirectory(Path.GetDirectoryName(options.Output)!);
File.WriteAllText(options.Output, generated, new UTF8Encoding(false));

static void ValidateContract(Assembly model)
{
    foreach (var name in new[]
    {
        "Voxta.Model.WebsocketMessages.ClientMessages.ClientAuthenticateMessage",
        "Voxta.Model.WebsocketMessages.ClientMessages.ClientStartChatMessage",
        "Voxta.Model.WebsocketMessages.ClientMessages.ClientSendMessage",
        "Voxta.Model.WebsocketMessages.ClientMessages.ClientInterruptMessage",
        "Voxta.Model.WebsocketMessages.ClientMessages.ClientSpeechPlaybackStartMessage",
        "Voxta.Model.WebsocketMessages.ClientMessages.ClientSpeechPlaybackCompleteMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerWelcomeMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerChatStartedMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerReplyStartMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerReplyChunkMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerReplyEndMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerSpeechPlaybackStartMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerSpeechPlaybackCompleteMessage",
        "Voxta.Model.WebsocketMessages.ServerMessages.ServerInterruptSpeechMessage"
        ,"Voxta.Model.WebsocketMessages.ServerMessages.ServerRecordingRequestMessage"
        ,"Voxta.Model.WebsocketMessages.ServerMessages.ServerSpeechRecognitionStartMessage"
        ,"Voxta.Model.WebsocketMessages.ServerMessages.ServerSpeechRecognitionPartialMessage"
        ,"Voxta.Model.WebsocketMessages.ServerMessages.ServerSpeechRecognitionEndMessage"
        ,"Voxta.Model.WebsocketMessages.ServerMessages.ServerAudioFrameMessage"
    })
        if (model.GetType(name) is null) throw new InvalidOperationException($"Pinned Voxta.Model is missing {name}.");
}

