sealed record Arguments(string Model, string Output, bool Check)
{
    public static Arguments Parse(string[] args)
    {
        string Value(string key) { var i = Array.IndexOf(args, key); return i >= 0 && i + 1 < args.Length ? args[i + 1] : throw new ArgumentException($"Missing {key}."); }
        return new Arguments(Value("--model"), Value("--output"), args.Contains("--check"));
    }
}
